/* 每节概念练习与章末综合题；选项答案和解析均按本章讲解编写。 */
let exerciseOrder = 0;
const exercise = (q, options, answer, why) => {
  const hash = Array.from(q).reduce((value, character) => (value * 31 + character.codePointAt(0)) >>> 0, 0);
  const answerPosition = (hash + exerciseOrder++ * 3) % options.length;
  const offset = (answer - answerPosition + options.length) % options.length;
  return { q, options: options.slice(offset).concat(options.slice(0, offset)), answer: answerPosition, why };
};
